"""Regenerate static HTML. Runtime needs no Python, packages or build step."""
from pathlib import Path
from html import escape as esc
import json
from history import render_history
from concepts import render_concepts
from architecture import render_architecture

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT / 'content/weeks.json').read_text(encoding='utf-8'))
SYLLABUS = json.loads((ROOT / 'content/syllabus.json').read_text(encoding='utf-8'))
def write(path, text):
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding='utf-8')
def head(title, description, prefix=''):
    return f'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | TBK · ÇOMÜ</title><meta name="description" content="{esc(description, quote=True)}"><meta property="og:title" content="{esc(title, quote=True)}"><meta property="og:description" content="{esc(description, quote=True)}"><meta property="og:type" content="website"><meta property="og:locale" content="tr_TR"><meta name="theme-color" content="#fafafc"><link rel="icon" href="{prefix}assets/icons/favicon.svg" type="image/svg+xml"><script src="{prefix}js/theme.js"></script><link rel="stylesheet" href="{prefix}css/style.css"><link rel="stylesheet" href="{prefix}css/presentation.css"><link rel="stylesheet" href="{prefix}css/responsive.css"><script defer src="{prefix}js/main.js"></script><script defer src="{prefix}js/presentation.js"></script><script defer src="{prefix}js/demos.js"></script></head>'''
def nav(prefix=''):
    return f'''<a class="skip" href="#main">İçeriğe geç</a><header class="topbar"><nav class="nav-inner" aria-label="Ana navigasyon"><a class="brand" href="{prefix}index.html"><span class="brand-mark" aria-hidden="true">TBK</span><span><strong>Temel Bilgi Teknolojileri</strong><small>ÇOMÜ · ELEKTRİK-ELEKTRONİK</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="primary-links" hidden>Menü <span aria-hidden="true">☰</span></button><div class="nav-links" id="primary-links"><a href="{prefix}index.html#program">Ders programı</a><a href="{prefix}index.html#proje">Dönem projesi</a><a href="{prefix}index.html#ai">AI ilkeleri</a></div><button class="theme-toggle" type="button" aria-label="Temayı değiştir">☾</button></nav></header>'''
def footer():
    return '''<footer class="footer"><div class="container"><div><strong>Çanakkale Onsekiz Mart Üniversitesi</strong><br>Mühendislik Fakültesi · Elektrik-Elektronik Mühendisliği</div><div>Temel Bilgi Teknolojileri · 2026-2027<br>Öğren. Sorgula. Üret.</div></div></footer></body></html>'''
def ul(items): return '<ul>'+''.join(f'<li>{esc(x)}</li>' for x in items)+'</ul>'
def code(text): return '<div class="code-wrap"><pre><code>'+esc(text)+'</code></pre></div>'
def table(headers, rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id, title, body): return f'<section class="lesson-section" id="{id}" aria-labelledby="{id}-title"><h2 id="{id}-title">{title}</h2>{body}</section>'

cards=''
for n,w in enumerate(SYLLABUS,1):
    cards+=f'''<a class="week-card" data-week="{n}" data-category="{w['category']}" href="weeks/week{n:02}.html"><div class="card-top"><span class="week-number">{n:02} / HAFTA</span><span class="tag">{w['group']}</span></div><h3>{w['title']}</h3><p>{w['intro']}</p><div class="card-bottom"><span class="card-status">2 saat · Ders notları</span><b aria-hidden="true">↗</b></div></a>'''
import re
# Planned weeks are noninteractive cards and require no JavaScript.
def planned_card(match):
    card = match.group(0)
    number = int(re.search(r'data-week="(\d+)"', card).group(1))
    if number <= len(DATA): return card
    card = re.sub(r'href="[^"]+"', 'aria-disabled="true"', card)
    return card.replace('<a ', '<div ', 1).replace('</a>', '</div>').replace('2 saat · Ders notları', 'Yakında · Ders planı').replace('↗', '◷')
cards = re.sub(r'<a class="week-card".*?</a>', planned_card, cards)
principles=['Yapay zekâ kullanımı serbesttir ve teşvik edilir.','Öğrenci, yapay zekânın ürettiği kodu anlayabilmelidir.','Öğrenci teslim ettiği kodu açıklayabilmelidir.','Yapay zekânın verdiği bilgiler doğrulanmalıdır.','Hatalı kodları düzeltmek öğrencinin sorumluluğundadır.','AI tarafından üretilen içerikler doğrudan kopyalanmamalı; incelenmeli ve geliştirilmelidir.','Öğrenciler kullandıkları önemli AI promptlarını proje dokümantasyonunda belirtebilir.','Git commit geçmişi öğrencinin çalışma sürecini göstermelidir.','Öğrenci yalnızca nihai üründen değil, çalışma ve öğrenme sürecinden de sorumludur.','Akademik etik ilkelerine uyulmalıdır.']
path=['Donanım','İşletim Sistemleri','İnternet ve Ağ','Web','Bulut','Veri Analizi','Gömülü Sistemler ve IoT','Yapay Zekâ']
write('index.html',head('Temel Bilgi Teknolojileri','2026-2027 · 14 haftalık etkileşimli ders portalı. Bilgisayar sistemlerinden web, bulut, IoT ve yapay zekâya.')+'<body>'+nav()+f'''<main id="main" class="container"><section class="hero"><div><div class="eyebrow">2026–2027 ÖĞRETİM DÖNEMİ · DERS PORTALI</div><h1>Teknolojiyi anla.<br><span>Geleceği tasarla.</span></h1><p><strong>Temel Bilgi Teknolojileri</strong><br>Bilgisayar Sistemlerinden Web, Bulut, Gömülü Sistemler ve Yapay Zekâ Teknolojilerine</p><p class="university">Çanakkale Onsekiz Mart Üniversitesi<br>Mühendislik Fakültesi · Elektrik-Elektronik Mühendisliği</p><div class="actions"><a class="button primary" href="weeks/week01.html">Öğrenmeye başla <span aria-hidden="true">→</span></a><a class="button" href="#program">Ders programını keşfet</a></div></div><aside class="course-preview" aria-label="Hazır dersler"><div class="preview-heading"><span class="eyebrow">ÖĞRENMEYE BİR ADIM</span><span class="ready-badge">2 hafta hazır</span></div><h2>Her büyük fikir,<br>bir temelle başlar.</h2><p>Ders notlarını keşfet, uygulamayla pekiştir.</p><a class="preview-lesson" href="weeks/week01.html"><span class="preview-number">01</span><span><strong>Bilgisayar sistemleri</strong><small>Tarih · Donanım · Etkileşimli zaman çizgisi</small></span><span aria-hidden="true">↗</span></a><a class="preview-lesson" href="weeks/week02.html"><span class="preview-number">02</span><span><strong>İşletim sistemleri</strong><small>Kernel · Bellek · Gömülü sistemler</small></span><span aria-hidden="true">↗</span></a><div class="preview-note"><span aria-hidden="true">✦</span> Kendi hızında öğren. Sınıfta sunumla takip et.</div></aside></section><div class="stats"><div class="stat"><strong>14 hafta</strong><span>Birbirine bağlı öğrenme yolculuğu</span></div><div class="stat"><strong>2 saat / hafta</strong><span>Toplam 28 saat</span></div><div class="stat"><strong>1 dönem projesi</strong><span>Akıllı Ortam İzleme Sistemi</span></div><div class="stat"><strong id="completed-count">0 / 14 hafta</strong><span>Bu cihazdaki ilerlemeniz</span><progress id="course-progress" max="14" value="0" aria-label="Tamamlanan haftalar"></progress></div></div><section id="program"><div class="section-heading"><div><span class="eyebrow">ADIM ADIM, BİRLİKTE</span><h2>14 haftalık öğrenme yolculuğu</h2><p>İlk 2 hafta hazır · 3–14. haftalar yakında.<br>Teori → Gerçek Sistem → Küçük Uygulama → GitHub Çalışması</p></div><span class="label">14 HAFTA / 28 SAAT</span></div><div class="filters" aria-label="Hafta filtreleri"><button data-filter="all" aria-pressed="true">Tüm haftalar</button><button data-filter="systems" aria-pressed="false">Sistemler</button><button data-filter="web" aria-pressed="false">Web</button><button data-filter="cloud" aria-pressed="false">Bulut & Veri</button><button data-filter="future" aria-pressed="false">Yeni teknolojiler</button><label class="sr-only" for="week-search">Hafta veya konu ara</label><input class="search" id="week-search" type="search" placeholder="Hafta veya konu ara…"></div><span id="filter-status" class="sr-only" aria-live="polite"></span><div class="week-grid">{cards}</div><p class="empty" id="empty-results" hidden>Eşleşen hafta yok. Başka bir konu arayın.</p></section><section class="panel" id="yaklasim"><span class="eyebrow">DERSİN AMACI</span><h2>Parçaları öğren, bütünü gör.</h2><p>Elektronik bir sistemin ölçtüğü sinyalin nasıl işlendiğini, ağ üzerinden taşındığını ve anlamlı bilgiye dönüştüğünü keşfedin. Her hafta yeni bir katman ekleyerek donanım, yazılım ve veriyi birlikte değerlendirin.</p><div class="learning-path">{('<i aria-hidden="true">→</i>').join('<span>'+x+'</span>' for x in path)}</div><p>Teknolojiyi yalnızca kullanan değil; teknolojinin nasıl çalıştığını anlayan, sorgulayan, geliştiren ve yeni teknolojiler üretebilen mühendisler yetiştirmek.</p></section><div class="feature-grid"><section class="panel" id="proje"><span class="eyebrow">DÖNEM BOYUNCA BİRLİKTE GELİŞTİR</span><h2>Akıllı Ortam<br>İzleme Sistemi</h2><p>Sıcaklık ve elektriksel ölçümleri toplayan, görselleştiren ve belgelenebilir bir web arayüzüne dönüştüren dönem projesi.</p><div class="diagram">Sensör → ESP32 → Wi-Fi → İnternet<br>↓<br>Web Arayüzü · HTML + CSS + JavaScript<br>↓<br>Veri → Google Sheets → Grafikler<br>↓<br>Google Sites / GitHub Pages</div><p>1–4: sistemi modelle · 5–7: arayüzü geliştir · 8–12: veriyi düzenle ve analiz et · 13: yayınla · 14: doğrula ve sun.</p><p>Donanım yoksa örnek CSV verisiyle çalışın. Sheets aktarımı bu portalda manuel CSV içe aktarma ile öğretilir. Canlı veri aktarımı ayrıca kimlik doğrulamalı bir servis gerektirir; gizli anahtarları tarayıcı koduna koymayın.</p><a class="button" href="assets/data/olcumler.csv" download>Örnek ölçüm verisini indir ↓</a></section><section class="panel"><span class="eyebrow">DÜŞÜNMEYE ALAN AÇ</span><h2>Yapay zekâyla öğren.<br>Sorumluluğu sahiplen.</h2><blockquote class="quote">Yapay zekâ öğrencinin yerine düşünmemeli; öğrencinin daha iyi düşünmesine, üretmesine ve öğrenmesine yardım etmelidir.</blockquote><p>Kodu açıklayın, çıktıyı sınayın ve teknik kararlarınızı belgeleyin. Her haftanın sonunda konuya özel bir prompt ve doğrulama adımları sizi bekliyor.</p><a class="button" href="#ai">Çalışma ilkelerini incele →</a></section></div><section class="panel" id="ai"><span class="eyebrow">AKADEMİK ETİK & ÜRETKENLİK</span><h2>Yapay Zekâ ile Çalışma İlkeleri</h2><ol>{''.join('<li>'+p+'</li>' for p in principles)}</ol><blockquote class="quote">Yapay zekâ kullanabilirsiniz. Ancak teslim ettiğiniz her satır kodun ve her teknik kararın sorumluluğu size aittir.</blockquote></section></main>'''+footer())

for n,w in enumerate(DATA,1):
    sections=[]
    sections.append(('hedefler','Öğrenme Hedefleri',ul(w['goals'])))
    concepts='<div class="concepts">'+''.join(f'<div class="concept"><strong>{esc(k)}</strong>{esc(v)}</div>' for k,v in w['concepts'])+'</div>'
    if n == 1: concepts = render_concepts(ROOT)
    sections.append(('kavramlar','Temel Kavramlar',concepts))
    if n == 1:
        sections.append(('bilgisayar-tarihi', 'Bilgisayarların Tarihi · Etkileşimli Zaman Çizgisi', render_history(ROOT)))
    for j,(title,text) in enumerate(w['lessons']):
        sections.append((f'konu-{j+1}', title, ''.join('<p>'+esc(p)+'</p>' for p in text.split('\n'))))
    if 'table' in w: sections.append(('karsilastirma','Karşılaştırma',table(w['table'][0],w['table'][1:])))
    architecture = render_architecture() if n == 1 else '<div class="diagram">'+esc(w['diagram'])+'</div><p>'+esc(w['architecture'])+'</p>'
    sections.append(('mimari','Sistem Mimarisi',architecture))
    sections.append(('ornek','Gerçek Dünya Örneği','<p>'+esc(w['example'])+'</p>'))
    practice=ul(w['practice'])+code(w['code'])
    if n==7: practice+='''<div class="demo"><p>Tarayıcı simülasyonu · fiziksel sensöre bağlı değildir.</p><button id="sensor-read">Sensör değerini güncelle</button><output id="sensor-value" aria-live="polite">25.0 °C (simülasyon)</output><button id="led-toggle" aria-pressed="false"><span class="led" id="led" aria-hidden="true"></span><span id="led-state">LED kapalı</span></button></div>'''
    if n==10: practice+='''<form class="demo" id="power-demo"><h3>Güç ve enerji hesaplayıcı</h3><label>Gerilim (V) <input name="voltage" type="number" min="0" step="0.1" value="12"></label><label>Akım (A) <input name="current" type="number" min="0" step="0.01" value="0.5"></label><label>Süre (saat) <input name="hours" type="number" min="0" step="0.1" value="2"></label><output id="power-result" aria-live="polite"></output></form>'''
    if n==11: practice+='''<h3>Örnek sıcaklık serisi</h3><div class="result-chart" role="img" aria-label="09:00 22 derece, 10:00 24 derece, 11:00 28 derece, 12:00 26 derece. Sütun tabanı sıfır derecedir."><div class="bar" style="height:73.3%">22°C</div><div class="bar" style="height:80%">24°C</div><div class="bar" style="height:93.3%">28°C</div><div class="bar" style="height:86.7%">26°C</div></div><p>Sırasıyla 09:00, 10:00, 11:00, 12:00 · Eksen tabanı: 0 °C. Değerler örnek CSV dosyasından alınmıştır.</p><a href="../assets/data/olcumler.csv" download>CSV verisini indir</a>'''
    sections.append(('uygulama','Uygulama',practice))
    sections.append(('ai-calisma','Yapay Zekâ ile Çalışma',code(w['prompt'])+'<h3>Doğrulama kontrolü</h3>'+ul(w['verify'])))
    quiz=''.join(f'<details><summary>{i}. {esc(q)}</summary><p>{esc(a)}</p></details>' for i,(q,a) in enumerate(w['quiz'],1))
    sections.append(('test','Kendini Test Et',quiz))
    sections.append(('gorev','Haftalık Çalışma','<p>'+esc(w['task'])+'</p>'+ul(['Çalışmayı kendi repository’nizde hafta'+f'{n:02}'+' klasörüne ekleyin.','En az 3 anlamlı commit: ilk çözüm, doğrulama/düzeltme, açıklama ve sonuç.','README içinde yaklaşımı, test sonucunu, kaynakları ve kullandığınız önemli AI promptlarını belirtin.','Teslim kontrolü: çalışan örnek, anlaşılır açıklama ve öğrenme sürecini gösteren commit geçmişi.'])))
    sources='<ul class="source-list">'+''.join(f'<li><a href="{url}">{esc(label)}</a></li>' for label,url in w['sources'])+'</ul><p class="muted">Arayüz adları ve ürün özellikleri değişebilir; uygulama öncesi resmî belgeleri kontrol edin.</p>'
    sections.append(('kaynaklar','Kaynaklar ve İleri Okuma',sources))
    toc=''.join(f'<a href="#{id}">{title}</a>' for id,title,_ in sections if not id.startswith('konu-'))
    previous=f'<a class="button" href="week{n-1:02}.html">← {n-1}. hafta</a>' if n>1 else '<a class="button" href="../index.html#program">← Ders programı</a>'
    next=f'<a class="button" href="week{n+1:02}.html">{n+1}. hafta →</a>' if n<len(DATA) else '<a class="button" href="../index.html#program">Ders programına dön →</a>'
    write(f'weeks/week{n:02}.html',head(w['title'],w['intro'],'../').replace('</head>', ('<link rel="stylesheet" href="../css/history.css"><script defer src="../js/history.js"></script><link rel="stylesheet" href="../css/concepts.css"><script defer src="../js/concepts.js"></script>' if n == 1 else '') + '</head>')+f'<body data-week="{n}">'+nav('../')+f'''<main id="main" class="container"><div class="breadcrumb"><a href="../index.html#program">Ders programı</a> / {n:02}. Hafta</div><header class="lesson-header"><span class="eyebrow">{n:02}. HAFTA · {w['group']} · 2 SAAT</span><h1>{w['title']}</h1><p>{w['intro']}</p><div class="actions"><button class="primary" id="start-presentation">▷ Sunum modunu başlat</button><a class="button" href="#uygulama">Uygulamaya geç</a></div><p class="muted">Sunum: ← → / Space · Home / End · F: tam ekran · Esc: çıkış<br>Önerilen akış: 15 dk hedefler · 50 dk teori · 35 dk uygulama · 20 dk değerlendirme</p></header><div class="lesson-layout"><aside class="toc"><details class="toc-disclosure" open><summary>Bu haftanın içindekileri</summary><span class="eyebrow">BU HAFTADA</span><nav aria-label="Ders içindekiler">{toc}</nav></details></aside><article aria-label="Haftalık ders içeriği">{''.join(section(*s) for s in sections)}<div class="completion"><button id="mark-complete" aria-pressed="false">Bu haftayı tamamladım</button><p class="muted">İlerleme yalnızca bu tarayıcıda saklanır; notlandırma amacı taşımaz.</p></div><nav class="week-nav" aria-label="Haftalar arası navigasyon">{previous}{next}</nav></article></div></main><div class="presentation-controls" hidden role="region" aria-label="Sunum denetimleri"><progress id="slide-progress" max="100" value="0" aria-label="Sunum ilerlemesi"></progress><button id="slide-prev" aria-label="Önceki slayt">←</button><output id="slide-count" aria-live="polite"></output><button id="slide-next" aria-label="Sonraki slayt">→</button><button id="slide-fullscreen">Tam ekran</button><button id="slide-exit">Çıkış (Esc)</button><span class="sr-only" id="presentation-message" aria-live="polite"></span></div>'''+footer())
print(f'Generated index.html and {len(DATA)} lesson pages.')
